function drawPolygon(pg, n, px, py, d, rot=0) {
	pg.beginShape();
	for (let i = 0; i < n; i++) { pg.vertex(cos(360/n*i+rot)*(d/2)+px, sin(360/n*i+rot)*(d/2)+py); }
	pg.endShape(CLOSE);
}

function polygonPoint(t, rot, n) {
	let an = 360 / n;
	return createVector(
		cos(t+rot) * (cos(an / 2) / cos(an * (t / an - floor(t / an)) - an / 2)),
		sin(t+rot) * (cos(an / 2) / cos(an * (t / an - floor(t / an)) - an / 2))
	);
}

function shadow(pg, bShadow, col=color(30), blur=10, offset=5) {
	if (bShadow) {
		pg.drawingContext.shadowOffsetX = offset;
		pg.drawingContext.shadowOffsetY = offset;
		pg.drawingContext.shadowBlur = blur;
		pg.drawingContext.shadowColor = col;
		// pg.drawingContext.shadowColor = color(30);
		// pg.drawingContext.shadowColor = color(200);
		// pg.drawingContext.shadowColor = color(pal[1]);
		// drawingContext.shadowColor = bgColor;
	} else {
		pg.drawingContext.shadowOffsetX = 0;
		pg.drawingContext.shadowOffsetY = 0;
		pg.drawingContext.shadowBlur = 0;
	}
}

function alphaColor(c,a){
	return color(hue(window.color(c)),saturation(window.color(c)),brightness(window.color(c)),a);
}

function genEffect() {
	let pg = createGraphics(width, height);
	pg.background(255, 10);

	// glitch
	pg.strokeWeight(1);
	for (let i = 0; i < width / 4; i++) {
		pg.stroke(red(window.color(bgColor)), green(window.color(bgColor)), blue(window.color(bgColor)), random(30));
		let px = random(width);
		let py = random(height);
		pg.line(px, py, px, py + 200);
	}

	// noise
	pg.strokeWeight(1);
	for (let i = 0; i < width * height / 20; i++) {
		pg.stroke(red(window.color(bgColor)), green(window.color(bgColor)), blue(window.color(bgColor)), random(100));
		var px = random(width);
		var py = random(height);
		pg.point(px, py);
	}

	return pg;
}

// === Tab: mySketch ===
let pal = [
	['#5A0785','#0FF370'],
	['#34363E','#E76146'],
	['#0E306F','#E0C13B'],
	['#202C76','#BB17DB'],
	['#2A043C','#D5B936'],
];
let c1,c2;

let bgColor;
let frb, tex, eff;
let texBuff, townBuff;
let sky;
let M=15;

function setup() {
	createCanvas(w=600, w);
	colorMode(HSB,360,100,100,100);
	// angleMode(DEGREES);
	background(255,100,10);
	// // noLoop() removed for animation

	c1 = color(pal[0][0]);
	c2 = color(pal[0][1]);

	bgColor = color(255,100,10);
	bgColor = color(50);
	bgColor = c1;
	background(bgColor);

	// eff = genEffect();

	/**
	 * Create texture layer buffer
	 */
	texBuff = [];
	for (let i = 0; i < 3; i++) { texBuff.push(genTexture(this,int(random(6)),0,0.2)); }

	/**
	 * Create sky layer
	 */
	sky = createGraphics(w*2,w*2);
	sky.colorMode(HSB,360,100,100,100);
	for (let i = 0; i < 3e+4; i++) {
		let a = random(Math.PI*2);
		let r = 50 * (1 - random(random(random())));
		let x = cos(a)*r+w/2*3;
		let y = sin(a)*r+w/2*3;
		sky.stroke(random(50,60),15,100);
		sky.point(x,y);
	}
	sky.erase();
	sky.circle(w/2*3+30,w/2*3+30,55);
	sky.noErase();
	for (let i = 0; i < 3e+4; i++) {
		var a = random(Math.PI*2);
		var r = 40 * (1 + random(random(random())));
		var x = cos(a)*r+w/2;
		var y = sin(a)*r+w/2;
		sky.stroke(random(60,30),15,100);
		sky.point(x,y);
	}

	/**
	 * Create effect layer
	 */
	tex = createGraphics(w,w);
	tex.colorMode(HSB,360,100,100,100);
	for (let i = 0; i < 3e+4; i++) {
		var a = random(Math.PI*2);
		var r = w/2*sqrt(2) * (1 - random(random(random(random()))));
		var x = cos(a)*r+w/2;
		var y = sin(a)*r+w/2;
		tex.stroke(100);  tex.strokeWeight(1.5);
		tex.point(x,y);
	}

	/**
	 * Create town layers
	 */
	townBuff = [];

	let cx, cy;
	cx = w;  cy = w;

	// Make town objects
	let ids = [];
	let xs = [];
	let ys = [];
	let ws = [];
	let hs = [];
	let as = [];
	let rs = [];
	for (let j = 0; j < M; j++) {
		let d = map(pow(j,0.8),0,pow(M-1,0.8),250,w*0.8);
		let n = 36*2;
		ids[j] = [];
		xs[j] = [];
		ys[j] = [];
		ws[j] = [];
		hs[j] = [];
		as[j] = [];
		rs[j] = [];
		for (let i = 0; i < n; i++) {
			ids[j].push(i);
			// let tw = 10+4*j+random(20);
			let tw = 10+j+random(20+j*5);
			let th = random(50,150+j*2);
			let ta = map(i,0,n,0,Math.PI*2);
			let tx = cos(ta)*(d-th/2)+cx;
			let ty = sin(ta)*(d-th/2)+cy;
			let tr = random()*tw/4;
			ws[j].push(tw);
			hs[j].push(th);
			as[j].push(ta);
			xs[j].push(tx);
			ys[j].push(ty);
			rs[j].push(tr);
		}
		ids[j] = shuffle(ids[j]);
	}

	// Draw towns on frame buffer
	for (let j = 0; j < ids.length; j++) {
		frb = createGraphics(w*2,w*2);
		shadow(frb,true,col=frb.color(map(j,0,M,10,200)-30),blur=3+j*2,offset=3+j);

		// let msk = createGraphics(w*2,w*2);
		for (let i = 0; i < ids[j].length; i++) {
			let k = ids[j][i];
			frb.push();
			frb.translate(xs[j][k],ys[j][k]);
			frb.rotate(as[j][k]+Math.PI/2);
			if (random()>(0.3*(j+1))) {
				frb.noFill();  frb.stroke(255);  frb.strokeWeight(3);
				frb.point(-ws[j][k]/2,hs[j][k]/2);
				frb.point(+ws[j][k]/2,hs[j][k]/2);
			}
			frb.rectMode(CENTER);
			frb.noStroke();  frb.fill(map(j,0,M,10,200));
			if (random()>0.9) { frb.noFill();  frb.stroke(map(j,0,M,10,200));  frb.strokeWeight(2); }
			frb.rect(0,0,ws[j][k],hs[j][k],rs[j][k]);
			// frb.quad(-ws[j][k]/2,-hs[j][k]/2,
			// 				 -ws[j][k]/2*(map(j,0,m,0.6,1.0)), hs[j][k]/2,
			// 				  ws[j][k]/2*(map(j,0,m,0.6,1.0)), hs[j][k]/2,
			// 				  ws[j][k]/2,-hs[j][k]/2);
			// frb.circle(0,0,10);
			frb.pop();
		}

		// Draw towns on mask buffer
		let mskBuff = [];
		for (let i = 0; i < texBuff.length; i++) { mskBuff.push(createGraphics(w*2,w*2)); }
		for (let i = 0; i < ids[j].length; i++) {
			var k = ids[j][i];
			// if (random()>0.9) { continue; }
			let msk = random(mskBuff);
			msk.push();
			msk.translate(xs[j][k],ys[j][k]);
			msk.rotate(as[j][k]+Math.PI/2);
			msk.rectMode(CENTER);
			msk.noStroke();
			msk.rect(0,0,ws[j][k],hs[j][k],random()*ws[j][k]/4);
			msk.pop();
		}

		// Mask and overlay texture on town
		for (let i = 0; i < texBuff.length; i++) {
			let tmp = mskBuff[i].get();
			tmp.mask(random(texBuff),0,0);
			frb.image(tmp,0,0);
		}

		// Draw wires
		var d = map(pow(j,0.8),0,pow(M-1,0.8),250,w*0.8);
		for (let i = 0; i < 30; i++) {
			frb.stroke(map(j,0,M,10,200));  frb.noFill();  frb.strokeWeight(2);
			var k = random(ids[j]);
			let h = d - hs[j][k] * (1 - random()/4);
			let s = random()>0.5?+1:-1;
			let a1 = as[j][k];
			let a2 = a1 + random() * map(j,0,M,1,0.4) * s;
			let a3 = a2 + random() * map(j,0,M,1,0.4) * s;
			let a4 = a3 + random() * map(j,0,M,1,0.4) * s;
			let x1 = cos(a1)*h + cx;
			let y1 = sin(a1)*h + cy;
			let x2 = cos(a2)*(d-h/5) + cx;
			let y2 = sin(a2)*(d-h/5) + cy;
			let x3 = cos(a3)*(d-h/5) + cx;
			let y3 = sin(a3)*(d-h/5) + cy;
			let x4 = cos(a4)*(d-h/5) + cx;
			let y4 = sin(a4)*(d-h/5) + cy;
			frb.bezier(x1,y1,x2,y2,x3,y3,x4,y4);
		}

		// Draw ambient
		let blr = createGraphics(w*2,w*2);
		blr.noStroke();  blr.fill(255);
		let gradientFill = blr.drawingContext.createRadialGradient(
			// w, w, d*map(j,0,M-1,0.45,0.75),
			w, w, d * map(pow(j,0.8),0,pow(M-1,0.8),0.45,0.75),
			w, w, d
		);
		gradientFill.addColorStop(0, blr.color(0,0,0,0));
		gradientFill.addColorStop(1, lerpColor(c2,c1,map(j,0,M-1,0,1)));
		blr.drawingContext.fillStyle = gradientFill;
		blr.circle(w,w,d*2);

		frb.image(blr,0,0);

		// Push in buffer
		townBuff.push(frb);
	}
}

function draw() {
	background(bgColor);

	var gradientFill = drawingContext.createRadialGradient(
		// w, w, d*map(j,0,M-1,0.45,0.75),
		w/2, w/2, 100,
		w/2, w/2, w/2,
	);
	gradientFill.addColorStop(0, color(10));
	gradientFill.addColorStop(1, bgColor);
	drawingContext.fillStyle = gradientFill;
	rect(0,0,w,w);

	// shadow(this,false);

	var cx, cy;
	cx = w/2;  cy = w/2;

	push();
	translate(w,w);
	rotate(frameCount*4e-3-Math.PI/4);
	imageMode(CENTER);
	image(sky,0,0);
	imageMode(CORNER);
	pop();

	noFill();  stroke(55,15,100);
	// arc(w,w,w*sqrt(2),w*sqrt(2),0+Math.PI,Math.PI+Math.PI);
	circle(w,w,w*sqrt(2));

	noFill();  stroke(55,15,100);
	circle(cos(frameCount*4e-3)*(w*sqrt(2)/2)+w,sin(frameCount*4e-3)*(w*sqrt(2)/2)+w,55*2);

	noFill();  stroke(55,15,100);
	// arc(w,w,w*sqrt(2),w*sqrt(2),0+Math.PI,Math.PI+Math.PI);
	circle(cos(frameCount*4e-3+Math.PI)*(w*sqrt(2)/2)+w,sin(frameCount*4e-3+Math.PI)*(w*sqrt(2)/2)+w,35*2);

	// shadow(this,true,col=color(10),blur=6,offset=3);

	for (let i = 0; i < M; i++) {
		push();
		translate(w/2,w/2);
		rotate(-frameCount*1e-4*(i+4));
		imageMode(CENTER);
		image(townBuff[i],0,0);
		imageMode(CORNER);
		pop();
	}

	fill(alphaColor(bgColor,20));  noStroke();
	rect(0,0,w,w);

	image(tex,0,0);

	// image(eff,0,0);
}
